211	function moveSideOf(entry: WorkspaceEntry, directory = entry.path): MoveSide {
212	  return syncStates.of(entry) === null
213	    ? { workspaceId: entry.id, directory }
214	    : { workspaceId: entry.id, directory, scratch: scratchRoot(app.getPath("userData"), entry.id) };
