217	/**
218	 * Finish every move the app died in (ADR 0033, decision 6). At startup and before each group.
219	 * An entry whose workspace is not connected waits for a later run.
220	 */
221	async function healPendingMoves(): Promise<void> {
222	  try {
223	    const report = await healMoves({ journalDir: movesJournalDir(), resolve: resolveMoveSide });
224	    if (report.healed > 0) host?.broadcastLibraryChanged();
225	    if (report.quarantined.length > 0) {
226	      console.error(
227	        `[workspaces] ${report.quarantined.length} interrupted move(s) need a look; journal kept in`,
228	        movesJournalDir(),
229	      );
230	    }
231	  } catch (error) {
